// Format Moroccan phone numbers to E.164 for Twilio.
// Optionally filters rows to tomorrow's appointments when a date column is present.
function toE164MA(raw) {
  if (raw == null || raw === '') return '';
  let phone = String(raw).replace(/[\s\-\(\)\.]/g, '');
  if (!phone) return '';
  if (phone.startsWith('+')) return phone;
  if (phone.startsWith('00')) return '+' + phone.slice(2);
  if (phone.startsWith('212')) return '+' + phone;
  if (phone.startsWith('0')) return '+212' + phone.slice(1);
  return '+212' + phone;
}

function getTomorrowDateKey() {
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  return tomorrow.toLocaleDateString('en-CA', { timeZone: 'Africa/Casablanca' });
}

function rowAppointmentDateKey(row) {
  const raw = row['Date & Heure du RDV'] ?? row.startTime ?? row.datetime ?? row.date;
  if (!raw) return '';
  const parsed = new Date(raw);
  if (Number.isNaN(parsed.getTime())) return '';
  return parsed.toLocaleDateString('en-CA', { timeZone: 'Africa/Casablanca' });
}

const tomorrowKey = getTomorrowDateKey();

return $input.all()
  .map((item) => item.json)
  .filter((row) => {
    const key = rowAppointmentDateKey(row);
    return !key || key === tomorrowKey;
  })
  .map((row) => {
    const nom = row['Patient (Nom Complet)'] ?? row.Clean_Name ?? row.Nom ?? 'Patient';
    const phone = toE164MA(row['Téléphone (WhatsApp)'] ?? row.Clean_Phone ?? row.telephone ?? '');
    return {
      json: {
        id: row.id,
        Nom: nom,
        Phone: phone,
        appointmentDate: rowAppointmentDateKey(row) || tomorrowKey
      }
    };
  })
  .filter((item) => item.json.Phone);
